@pytest.mark.parametrize('group_entries', [True, False])
def test_create_index_with_unicode_symbols(app, group_entries):
    words = ['← arrow', 'zebra', '£ pound', 'éclair', '@ at', '_private',
             'alpha', '9 digit']
    text = ''.join('.. index:: %s\n.. index:: parent; %s\n' % (word, word)
                   for word in words)
    restructuredtext.parse(app, text)
    index = IndexEntries(app.env).create_index(app.builder, group_entries=group_entries)

    assert [(heading, [word for word, entry in entries])
            for heading, entries in index] == [
        ('Symbols', ['9 digit', '@ at', '£ pound', '← arrow']),
        ('_', ['_private']),
        ('A', ['alpha']),
        ('E', ['éclair']),
        ('P', ['parent']),
        ('Z', ['zebra']),
    ]
    subentries = index[4][1][0][1][1]
    assert [word for word, targets in subentries] == [
        '9 digit', '@ at', '£ pound', '← arrow', '_private', 'alpha', 'éclair', 'zebra',
    ]


